INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "李善长", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "1353年受朱元璋留为幕书记。", "biography": null, "status": "draft", "id": "fcb986aa-d440-5732-984a-f4c744f5a06d"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "胡廷瑞", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "陈友谅江西丞相，降吴，康泰舅。", "biography": null, "status": "draft", "id": "802e1135-35a4-5a18-8000-e933e784a608"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"name": "陈友定（元福建参政）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "福建参政，复汀州。", "biography": null, "status": "draft", "id": "116044d6-cea0-5450-96d8-a4d9b1db3059"}, {"name": "廖永忠", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴水军将，1361年破安庆水寨。", "biography": null, "status": "draft", "id": "ccd9ff8d-290a-5c16-b1c7-90eeb0f8d3ee"}, {"name": "朱亮祖", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "义兵元帅，先降朱又叛，1357年宁国被擒获释。", "biography": null, "status": "draft", "id": "5c1a83a7-a770-5dc7-9fbd-e713e03e8e72"}, {"name": "常遇春", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "怀远人，1355年投朱元璋、采石先登。", "biography": null, "status": "draft", "id": "51d50a75-07e1-574f-b22d-1fded66288ff"}, {"name": "杨璟", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "吴亲军副都指挥，1358年随朱攻婺。", "biography": null, "status": "draft", "id": "de35b4c9-584c-5f2a-b297-a979743d7555"}, {"name": "周德兴", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "吴后明左丞，1367年奉命取广西，1368年取全州。", "biography": null, "status": "draft", "id": "b38e5f86-1f46-53af-90e5-784532a2661c"}, {"name": "邓愈", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年从朱元璋设伏擒陈埜先。", "biography": null, "status": "draft", "id": "5fbf3347-c8f3-5eaa-aa83-d0681e64b192"}, {"name": "左君弼", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "庐州军首领，与巢湖军有隙。", "biography": null, "status": "draft", "id": "a8301798-a3fe-5903-93f4-272b28947acf"}, {"name": "何真（元广东左丞）", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "元广东左丞，1368年献地降明入朝，授江西参政。", "biography": null, "status": "draft", "id": "05e37734-ea46-5861-9aad-ddc7a146435b"}, {"name": "冯国胜", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴将，参与伏击陈友谅及追击战。", "biography": null, "status": "draft", "id": "11681f87-f6f7-58db-93b2-dad66d159d27"}, {"name": "刘基", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "青田人，反对招抚方国珍被谪，曾任儒学副提举。", "biography": null, "status": "draft", "id": "bb5b8872-dbd3-576b-b02d-3b844e5a38e7"}, {"name": "库库特穆尔（察罕特穆尔养子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "本姓王名保保，察罕外甥，养为子；继掌其军。", "biography": null, "status": "draft", "id": "c00ceaa1-c47d-5d7f-bbe7-4c2ba9cfe8df"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱元璋建明称帝，立马后、太子标", "description": "朱元璋在南郊祭天地，即皇帝位，定国号明，年号洪武，追尊四代父祖及其配偶，立马氏为皇后、世子标为皇太子，以李善长为左丞相、徐达为右丞相。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "99e92a05-e27c-5dad-a52b-e51faec247ac"}, {"title": "朱元璋设朝臣兼任东宫官，不采用元太子中书令制", "description": "周宗请求重视教导太子，获准。中书省、都督府请仿元制，以太子为中书令，朱元璋拒绝，命詹同考察历代制度，由李善长、徐达、常遇春等兼任东宫官，以免另设府僚后发生嫌隙。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f470c02c-e216-5c59-a88b-e84faa1d2611"}, {"title": "明廷派人核查浙西田地，规定卫所制度", "description": "明廷派使者核实浙西田地，规定全国卫所制度。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c644bfdc-56e7-502c-ad6d-cd72cb18d71a"}, {"title": "胡廷瑞攻克建宁", "description": "胡廷瑞攻克建宁。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aa591b82-345b-5356-8032-78e5e479beaa"}, {"title": "汤和攻取延平，陈友定父子被处死", "description": "陈友定守延平，不许出战，又疑部下反叛，杀死萧院判。军器局起火，汤和加紧进攻。陈友定服药寻死，被抬出后在雷雨中苏醒，遭押送建康。朱元璋责问，陈友定以死抗拒，父子一同被杀。兴化、泉州投降，漳州守将迪里密实用刀刺喉而死。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a6f2861-4d07-52cd-89cd-2500550a4451"}, {"title": "明廷规定郊庙社稷的亲祭制度", "description": "明廷规定，冬至祭天、夏至祭地，宗庙在四孟月及除夕合计五祭，社稷在春秋仲月戊日祭祀，每年须由皇帝亲祭。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05edab84-8104-5589-8acb-c865b63f0421"}, {"title": "廖永忠、朱亮祖奉命从海路进取广东", "description": "明廷任廖永忠为征南将军、朱亮祖为副将，从海路进取广东。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "10750bfb-2b6b-58c8-a1b5-52681ac02740"}, {"title": "明廷祭祀孔子，遣使到阙里行祭", "description": "明廷在国学祭祀孔子，又派使者到阙里行祭。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "20f05353-9f04-532d-b7ef-5b119a8b8675"}, {"title": "朱元璋亲祭大社、大稷", "description": "朱元璋亲祭大社、大稷。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "87142cb5-3a6b-5225-ae24-6a151d44600d"}, {"title": "明廷规定衣冠仿唐制", "description": "明廷规定衣冠仿照唐制。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "14c97793-a730-5b5d-a60e-7471c22fd9d9"}, {"title": "常遇春取东昌，与徐达会军进取河南", "description": "常遇春攻下东昌，申荣、王辅元死难。他与徐达在济南会合，杀死乐安反叛者，返回济宁，率水军沿河向上进取河南。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6eb4066e-06ae-5d5e-ad61-2ffd6f0a8678"}, {"title": "杨璟攻取宝庆", "description": "杨璟攻取宝庆。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f0983044-a693-57fd-b1f1-ab639380a14f"}, {"title": "周德兴攻取全州", "description": "周德兴攻取全州。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7fde2a14-2318-5eea-b734-852c2e71b6b8"}, {"title": "邓愈取南阳，徐达等进取汴梁", "description": "邓愈攻取南阳，随后徐达等进取汴梁，李克彝逃走，左君弼、竹昌投降。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05ef6642-1a95-5d93-a7a9-4a64523dfe95"}, {"title": "何真献广东归降，获任江西参政", "description": "廖永忠率水军从福州出发，航海趋潮州。何真派刘克佐献郡县、户口簿及降表，朱元璋褒奖。何真迎军后奉诏入朝，获任江西参政。陆仲亨又攻取连州、肇庆，广东平定。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "67310e3d-caee-5455-a2a2-44eed6615c7f"}, {"title": "明廷开始太庙合祭，免山东田租三年", "description": "明廷开始在太庙合祭，免山东田租三年。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "721370a3-17a3-5754-a2f3-9c1e08def536"}, {"title": "常遇春在洛水北击败托音特穆尔，梁王投降", "description": "徐达、常遇春进入洛阳，托音特穆尔率五万兵在洛水北列阵。常遇春突入敌阵，射杀前锋，明军将其击败，梁王阿哩兖献河南投降。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0dad028b-a6ef-545a-babc-7f549dcc1702"}, {"title": "杨璟攻克永州", "description": "杨璟攻克永州。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2e451fcc-e711-5a8d-b30d-d7c99b87bc9e"}, {"title": "朱元璋赴汴梁", "description": "朱元璋前往汴梁。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "07307886-3c4e-5fa9-bdfa-8d81160d3c42"}, {"title": "冯胜攻潼关，明军向西进到华州", "description": "徐达攻取嵩、陕、陈、汝诸州，派冯胜进攻潼关。李思齐逃往凤翔，张良弼逃往鄜城。五月，明军入关，向西进到华州。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2d555b92-b15a-5402-aaec-6b214c171e06"}, {"title": "廖永忠取梧州等地，分兵会合继续进取广西", "description": "廖永忠到梧州，拜珠投降，随后取得浔州、柳州，又派朱亮祖会合杨璟，攻取尚未归附的州郡。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b981075c-f086-5940-a7e6-16c381009153"}, {"title": "明廷将汴梁路改为开封府", "description": "明廷将汴梁路改为开封府。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "67b351e4-0515-510a-b4d2-b1e80625e24e"}, {"title": "杨璟决濠攻克靖江，禁止张彬屠民", "description": "杨璟命邱广决开靖江西濠，筑五道土堤逼近城墙，将城攻下。张彬此前受守军辱骂，想屠杀百姓，被杨璟立即禁止。后来杨璟进取彬州，黄英、岑伯颜投降，廖永忠也攻取南宁、象州，广西平定。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "866b2922-96df-59a6-9781-c7f0aa9615f2"}, {"title": "朱元璋告诫北伐将领，善待百姓和元宗室", "description": "朱元璋准备离开汴梁，告诫徐达等将领，破城后不得掠夺、焚毁，要使市场照常、百姓安生，并善待元朝宗室亲属。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "13e30857-de6b-566a-9b69-de62798d3226"}, {"title": "冯胜奉命以右副将军留守开封", "description": "明廷命冯胜以右副将军身份留守开封。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "19062530-ae9e-5eab-a1a7-8aaf8086be2f"}, {"title": "元顺帝不听死守劝谏，半夜离京北走", "description": "元顺帝召集后妃、元皇太子及太子妃，商议避兵北行。实勒们、赫色、赵巴延布哈等反对，赵巴延布哈痛哭，请求率军民出城抵抗、让皇帝固守京城。元顺帝最终没有听从，半夜打开健德门向北逃走。", "start_year": 1368, "end_year": 1368, "time_original": "《续资治通鉴》卷220；本事原载纪年折合公元1368年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "193c2745-f7e7-5ce9-b045-510321c53ccb"}, {"title": "明廷定应天为南京、开封为北京", "description": "八月己巳，明廷定应天为南京、开封为北京。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "86fb95d3-8383-5711-9d5e-8b675d144a34"}, {"title": "徐达入元都并封存府库图籍", "description": "八月庚午，徐达进入元都，封存府库和图籍，派人守卫宫门，禁止士卒侵扰百姓，又派将领巡守古北口等处关隘。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c1105e6c-fec5-5dc8-a140-1d9f31aed358"}, {"title": "明廷制定六部官制", "description": "八月丁丑，明廷制定六部官制。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a79b5a6b-809d-5b38-8290-44c3c9401ee3"}, {"title": "御史中丞刘基致仕", "description": "八月，御史中丞刘基退休。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "326f9754-379e-5a36-affc-936b7792f3f1"}, {"title": "朱元璋下诏访求人才", "description": "九月，朱元璋下诏访求有才能的人，表示愿与儒士商议治理国家的办法，命地方官以礼送他们来朝。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fab5aca4-2d82-5e8e-a2a0-261c6ea5493c"}, {"title": "常遇春攻取保定和真定", "description": "九月乙丑，常遇春攻取保定，随后取得真定。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "34cf248b-cd9b-504d-8fb5-180cf01bdf8a"}, {"title": "冯胜、汤和攻下怀庆", "description": "十月庚午，冯胜、汤和攻下怀庆，泽州、潞州随后相继被攻取。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "48c3b05b-3003-53c9-b8bc-31384ce2b550"}, {"title": "明廷向天下发布平定元都的诏书", "description": "十月戊寅，明廷就平定元都一事向天下颁发诏书。", "start_year": 1368, "end_year": 1368, "time_original": "洪武元年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "845bb007-4d9f-5285-a13f-d6a27d34817f"}, {"title": "朱元璋下诏召刘基回朝", "description": "十一月癸亥，朱元璋下诏召刘基回来。 按原历纪年，事情发生在公元1368至1369年之间。", "start_year": null, "end_year": null, "time_original": "洪武元年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8c0f0d10-5b64-51bd-86cf-a73d3222c376"}, {"title": "明廷开始在圜丘祭祀上帝", "description": "十一月庚子，明朝开始在圜丘祭祀上帝。 按原历纪年，事情发生在公元1368至1369年之间。", "start_year": null, "end_year": null, "time_original": "洪武元年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "552015d2-61a0-5e7b-bed0-19b206c53f9e"}, {"title": "徐达攻克太原", "description": "十二月丁卯，徐达攻克太原，扩廓帖木儿逃往甘肃，本纪记山西平定。", "start_year": 1369, "end_year": 1369, "time_original": "洪武元年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "42e42db3-71e4-53cc-8dae-bb1b0ac4e58b"}, {"title": "明廷设置登闻鼓", "description": "十二月己巳，明廷设置登闻鼓。", "start_year": 1369, "end_year": 1369, "time_original": "洪武元年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bd71dc01-020f-5726-bddd-478d83afa8df"}]'::jsonb)
